\begin{equation}\label{eq:effective}
E=\frac12m\dot r^2+U_{\mathrm{eff}}(r),\qquad
\boxed{U_{\mathrm{eff}}(r)=U(r)+\frac{L^2}{2mr^2}.}
\end{equation}
